questions.question:
What is the output of the following C code?

```c
#include <stdio.h>
int main() {
    int x = 5;
    printf("%d %d %d", x, x++, ++x);
    return 0;
}
```

What is the output of the following C code?

```c
#include <stdio.h>
int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int *p = arr;
    printf("%d", *(p + 3));
    return 0;
}
```

What is the output of the following C++ code?

```cpp
#include <iostream>
using namespace std;
class Base {
public:
    virtual void show() { cout << "Base"; }
};
class Derived : public Base {
public:
    void show() { cout << "Derived"; }
};
int main() {
    Base *ptr = new Derived();
    ptr->show();
    return 0;
}
```

What is the output of the following C code?

```c
#include <stdio.h>
int main() {
    int i;
    for (i = 0; i < 5; i++) {
        if (i == 3)
            continue;
        if (i == 4)
            break;
        printf("%d ", i);
    }
    return 0;
}
```
